// Pseudo: idempotent processing with dedup on eventId
class KCNAConsumer {
  constructor(store){ this.dedup = store; }
  async handle(event){
    if (await this.dedup.has(event.id)) return; // dedup
    await this.apply(event);
    await this.dedup.set(event.id, true);
    await this.commitOffset(event.offset);
  }
  async apply(e){ /* apply business logic per tenant */ }
  async commitOffset(o){ /* persist committed offset per tenant */ }
}
```

